module inv_sv(input logic a, output logic y);
  assign y = ~a;
endmodule

module inv_sv_tb;
  logic a; logic y; integer errors;
  inv_sv dut(.a(a), .y(y));
  initial begin
    errors = 0;
    a = 1'b0; #1; if (y !== 1'b1) errors = errors + 1;
    a = 1'b1; #1; if (y !== 1'b0) errors = errors + 1;
    $display("a=%b y=%b", a, y);
    if (errors == 0) $display("PASS"); else $display("FAIL");
    $finish;
  end
endmodule

