module cnt_sv(input logic clk, input logic rst, output logic [3:0] count, output logic is_max);
  always_ff @(posedge clk) begin
    if (rst) count <= 4'd0;
    else count <= count + 4'd1;
  end
  always_comb begin
    is_max = (count == 4'd15);
  end
endmodule

module cnt_sv_tb;
  logic clk, rst; logic [3:0] count; logic is_max; integer errors, i;
  cnt_sv dut(.clk(clk), .rst(rst), .count(count), .is_max(is_max));
  initial clk = 0;
  always #5 clk = ~clk;
  initial begin
    errors = 0; rst = 1; #12; rst = 0;
    for (i = 1; i <= 15; i = i + 1) begin
      @(posedge clk); #1;
      if (count !== i) errors = errors + 1;
    end
    $display("count=%0d is_max=%b", count, is_max);
    if (is_max !== 1'b1) errors = errors + 1;
    if (errors == 0) $display("PASS"); else $display("FAIL");
    $finish;
  end
endmodule

