module add4(input logic [3:0] a, input logic [3:0] b, output logic [4:0] sum);
  assign sum = a + b;
endmodule

module add4_tb;
  logic [3:0] a, b; logic [4:0] sum; integer ia, ib, errors;
  add4 dut(.a(a), .b(b), .sum(sum));
  initial begin
    errors = 0;
    for (ia = 0; ia < 16; ia = ia + 1)
      for (ib = 0; ib < 16; ib = ib + 1) begin
        a = ia; b = ib; #1;
        if (sum !== ia + ib) errors = errors + 1;
      end
    $display("256 vectors, errors=%0d", errors);
    if (errors == 0) $display("PASS"); else $display("FAIL");
    $finish;
  end
endmodule
